CREATE DATABASE IF NOT EXISTS tourist_bus_db;
USE tourist_bus_db;

SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS Booking;
DROP TABLE IF EXISTS Bus_Seat;
DROP TABLE IF EXISTS Customer;
DROP TABLE IF EXISTS Tour_Guide;
DROP TABLE IF EXISTS Driver;
DROP TABLE IF EXISTS Bus;
DROP TABLE IF EXISTS Package;
DROP TABLE IF EXISTS Hotel_Room_Type;
DROP TABLE IF EXISTS Hotel;
DROP TABLE IF EXISTS Hotel_Name;
DROP TABLE IF EXISTS Tourist_Spot;

SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE Tourist_Spot (
  Spot_Name VARCHAR(100) PRIMARY KEY
);



CREATE TABLE Hotel (
  Hotel_ID INT PRIMARY KEY,
  Hotel_Name VARCHAR(150) NOT NULL UNIQUE,
  Star_Rating VARCHAR(30) NOT NULL,
  Address VARCHAR(255) NOT NULL
);

CREATE TABLE Hotel_Room_Type (
  Hotel_ID INT NOT NULL,
  Room_Type VARCHAR(80) NOT NULL,
  Room_Price_Per_Day INT NOT NULL,
  PRIMARY KEY (Hotel_ID, Room_Type),
  FOREIGN KEY (Hotel_ID) REFERENCES Hotel(Hotel_ID)
);

CREATE TABLE Package (
  Package_ID INT PRIMARY KEY,
  Package_Name VARCHAR(150) NOT NULL,
  Hotel_Name VARCHAR(150),
  Duration_Days INT NOT NULL,
  Nights INT NOT NULL,
  Route_Name VARCHAR(500) NOT NULL,
  Distance_KM DECIMAL(6,2) NOT NULL,
  Price INT NOT NULL,
  Breakfast_Included INT NOT NULL,
  Lunch_Included INT NOT NULL,
  Dinner_Included INT NOT NULL,
  Evening_Snacks_Included INT NOT NULL,
  FOREIGN KEY (Hotel_Name) REFERENCES Hotel(Hotel_Name)
);

CREATE TABLE Bus (
  Bus_no INT PRIMARY KEY,
  Bus_Type VARCHAR(10) NOT NULL
);

CREATE TABLE Driver (
  Driver_ID INT PRIMARY KEY,
  Driver_Name VARCHAR(100) NOT NULL,
  Contact_No VARCHAR(20) NOT NULL,
  Bus_no INT NOT NULL UNIQUE,
  FOREIGN KEY (Bus_no) REFERENCES Bus(Bus_no)
);

CREATE TABLE Tour_Guide (
  Guide_ID INT PRIMARY KEY,
  Guide_Name VARCHAR(100) NOT NULL,
  Contact_No VARCHAR(20) NOT NULL,
  Bus_no INT NOT NULL UNIQUE,
  FOREIGN KEY (Bus_no) REFERENCES Bus(Bus_no)
);

CREATE TABLE Customer (
  Customer_ID INT PRIMARY KEY,
  Customer_Name VARCHAR(100) NOT NULL,
  Customer_Age INT NOT NULL,
  Phone_No VARCHAR(20) NOT NULL UNIQUE,
  Package_ID INT NOT NULL,
  UNIQUE (Customer_ID, Phone_No),
  FOREIGN KEY (Package_ID) REFERENCES Package(Package_ID)
);

CREATE TABLE Bus_Seat (
  Bus_no INT NOT NULL,
  Seat_No INT NOT NULL,
  PRIMARY KEY (Bus_no, Seat_No),
  CHECK (Seat_No BETWEEN 1 AND 16),
  FOREIGN KEY (Bus_no) REFERENCES Bus(Bus_no)
);

CREATE TABLE Booking (
  Booking_ID INT PRIMARY KEY,
  Status VARCHAR(20) NOT NULL CHECK (Status IN ('Confirmed', 'Pending', 'Cancelled')),
  Package_ID INT NOT NULL,
  Bus_no INT NOT NULL,
  Seat_No INT NOT NULL,
  Guide_ID INT NOT NULL,
  Customer_ID INT NOT NULL,
  Phone_No VARCHAR(20) NOT NULL,
  UNIQUE (Bus_no, Seat_No),
  FOREIGN KEY (Package_ID) REFERENCES Package(Package_ID),
  FOREIGN KEY (Bus_no, Seat_No) REFERENCES Bus_Seat(Bus_no, Seat_No),
  FOREIGN KEY (Guide_ID) REFERENCES Tour_Guide(Guide_ID),
  FOREIGN KEY (Customer_ID, Phone_No) REFERENCES Customer(Customer_ID, Phone_No)
);

