-- Show tables in the requested order, then remaining lookup tables.
SELECT 'Tourist Spot Table' AS Table_Name;
SELECT * FROM Tourist_Spot;

SELECT 'Hotel Table' AS Table_Name;
SELECT * FROM Hotel;

SELECT 'Hotel Room Type Table' AS Table_Name;
SELECT * FROM Hotel_Room_Type;
SELECT 'Package Table' AS Table_Name;
SELECT * FROM Package;

SELECT 'Bus Table' AS Table_Name;
SELECT * FROM Bus;

SELECT 'Driver Table' AS Table_Name;
SELECT * FROM Driver;

SELECT 'Tour Guide Table' AS Table_Name;
SELECT * FROM Tour_Guide;

SELECT 'Bus Seat Table' AS Table_Name;
SELECT * FROM Bus_Seat;

SELECT 'Customer Table' AS Table_Name;
SELECT * FROM Customer;

SELECT 'Booking Table' AS Table_Name;
SELECT * FROM Booking;

SELECT 'Available Seat Table' AS Table_Name;

SELECT Bus_no, Seat_No
FROM Bus_Seat
WHERE Seat_No NOT IN (
    SELECT Seat_No
    FROM Booking
    WHERE Booking.Bus_no = Bus_Seat.Bus_no
      AND (Status = 'Confirmed' OR Status = 'Pending')
)
ORDER BY Bus_no, Seat_No;

-- 1. Customer-এর সব তথ্য এবং তার Package-এর সব তথ্য
SELECT *
FROM Customer, Package
WHERE Customer.Customer_ID = 13201
  AND Customer.Package_ID = Package.Package_ID;


-- 2. Bus 400-এর confirmed seat ও customer-এর তথ্য
SELECT *
FROM Customer, Booking
WHERE Customer.Customer_ID = Booking.Customer_ID
  AND Booking.Bus_no = 400
  AND Booking.Status = 'Confirmed'
ORDER BY Booking.Seat_No;


-- 3. Bus 400-এর available seat
-- Confirmed ও Pending seat বাদ যাবে; Cancelled seat available হিসেবে আসবে।
USE tourist_bus_db;

SELECT Bus_no, Seat_No, Status
FROM Booking
WHERE Bus_no = 400
  AND Status = 'Cancelled';



-- 4. COUNT দিয়ে Bus 401-এর available seat গোনা
SELECT COUNT(Seat_No) AS Available_Seat_Count
FROM Bus_Seat
WHERE Bus_no = 401
  AND Seat_No NOT IN (
      SELECT Seat_No
      FROM Booking
      WHERE Bus_no = 401
        AND (Status = 'Confirmed' OR Status = 'Pending')
  );


-- 5. AND: Package 201-এর customer দেখাবে, Customer 13201-কে বাদ দিয়ে
SELECT *
FROM Customer
WHERE Package_ID = 201
  AND Customer_ID != 13201;


-- 6. NOT দিয়ে একই শর্ত লেখা
SELECT *
FROM Customer
WHERE Package_ID = 201
  AND NOT Customer_ID = 13201;


-- 7. শুধু Customer 13201-এর তথ্য
SELECT *
FROM Customer
WHERE Customer_ID = 13201;


-- 8. OR: Non-AC bus অথবা bus 401 দেখাবে
SELECT *
FROM Bus
WHERE Bus_Type = 'Non-AC'
   OR Bus_no = 401;


-- 9. SUM দিয়ে সব Package-এর price যোগ
SELECT SUM(Price) AS Total_Package_Price
FROM Package;


-- 10. Confirmed booking-গুলোর Package price যোগ
SELECT SUM(Package.Price) AS Total_Confirmed_Booking_Price
FROM Package, Booking
WHERE Package.Package_ID = Booking.Package_ID
  AND Booking.Status = 'Confirmed';


-- 11. Package price ছোট থেকে বড় সাজানো
SELECT *
FROM Package
ORDER BY Price ASC;


-- 12. Customer-দের নাম alphabetically সাজানো
SELECT *
FROM Customer
ORDER BY Customer_Name ASC;


-- 13. Package price বড় থেকে ছোট সাজানো
SELECT *
FROM Package
ORDER BY Price DESC;


-- 14. Bus table-এ নতুন Practice_Note column যোগ করার উদাহরণ
ALTER TABLE Bus ADD COLUMN Practice_Note VARCHAR(100);


-- 15. Practice_Note column মুছে ফেলার উদাহরণ
-- আগে উপরের query চালাতে হবে।
ALTER TABLE Bus DROP COLUMN Practice_Note;


-- 16. Customer 13201-এর age 30 করার UPDATE উদাহরণ
-- চালালে Customer-এর data বদলাবে।
UPDATE Customer
SET Customer_Age = 30
WHERE Customer_ID = 13201;


-- 17. SOME: Package 201-এর অন্তত একজন customer-এর চেয়ে বয়স বেশি
SELECT *
FROM Customer
WHERE Customer_Age > SOME (
    SELECT Customer_Age
    FROM Customer
    WHERE Package_ID = 201
);


-- 18. ALL: Package 201-এর সব customer-এর চেয়ে বয়স বেশি
SELECT *
FROM Customer
WHERE Customer_Age > ALL (
    SELECT Customer_Age
    FROM Customer
    WHERE Package_ID = 201
);


-- 19. IN: যেসব Package-এর price 5000-এর বেশি,
-- সেগুলো নেওয়া customer দেখাবে
SELECT *
FROM Customer
WHERE Package_ID IN (
    SELECT Package_ID
    FROM Package
    WHERE Price > 5000
);


-- 20. প্রতিটি bus-এর booking সংখ্যা গোনা
SELECT Bus_no, COUNT(Booking_ID) AS Booking_Count
FROM Booking
GROUP BY Bus_no
HAVING COUNT(Booking_ID) > 0;